// Node.js (ESM) port of test18.py — JSON Schema Draft-7 error counting
// with ErrorTree, mirroring the jsonschema Python package's behaviour.

import { parseArgs } from './lib/argparse.mjs';
import { Draft7Validator } from './lib/validator.mjs';
import { ErrorTree } from './lib/errorTree.mjs';

const args = parseArgs(process.argv.slice(2), [
  { name: 'a', required: true, help: 'instance (JSON string)' },
  { name: 'b', required: true, help: 'schema (JSON string)' },
]);

const instance = JSON.parse(args.a);
const schema = JSON.parse(args.b);

const validator = new Draft7Validator(schema);

// Build error tree
const errors = [...validator.iter_errors(instance)]; // Get all errors
const tree = new ErrorTree(errors); // Build error tree

// Navigate tree
const total = tree.total_errors; // Total errors in tree

// Iterate multiple times
const first_pass = [...validator.iter_errors(instance)];
const second_pass = [...validator.iter_errors(instance)];

// Check instance multiple times with different approaches
const check1 = validator.is_valid(instance);
const check2 = validator.is_valid(instance);
const check3 = validator.is_valid(instance);

// Validate schema multiple times
const schema_check1 = validator.check_schema(schema);
const schema_check2 = validator.check_schema(schema);

// Create error trees for each pass
const tree1 = new ErrorTree(first_pass);
const tree2 = new ErrorTree(second_pass);

const pyBool = (v) => (v ? 'True' : 'False');
const pyNone = (v) => (v === undefined || v === null ? 'None' : String(v));

console.log(total);
console.log(first_pass.length);
console.log(second_pass.length);
console.log(pyBool(check1));
console.log(pyBool(check2));
console.log(pyBool(check3));
console.log(pyNone(schema_check1));
console.log(pyNone(schema_check2));
console.log(tree1.total_errors);
console.log(tree2.total_errors);

