  ['"blue"', '{"enum":["red","green"]}'],
  ['1', '{"enum":[1,2,3]}'],
  ['4', '{"enum":[1,2,3]}'],
  // enum Python equality: bool vs number
  ['true', '{"enum":[1]}'],
  ['false', '{"enum":[0]}'],
  ['1', '{"enum":[true]}'],
  ['0', '{"enum":[false]}'],
  ['2', '{"enum":[true]}'],
