  ['{"a":[1,true]}', '{"enum":[{"a":[1.0,2]}]}'],
  ['[1,[2,[3]]]', '{"enum":[[1,[2,[3]]]]}'],
  ['[1,[2,[3]]]', '{"enum":[[1,[2,[4]]]]}'],
  ['null', '{"enum":[null,false]}'],
  ['null', '{"enum":[false]}'],
