const cases = [
  // multi-failure counting
  ['"z"', '{"type":"integer","enum":["y"],"const":"x"}'],           // 3 errors
  ['1.5', '{"type":"integer","const":1.5}'],                        // type only fails
  ['1.5', '{"type":"number","const":1.5}'],                         // 0
  ['true', '{"type":["integer","boolean"],"const":1}'],             // const fails only
  // deep bool strictness
  ['[[true]]', '{"enum":[[[1]]]}'],
  ['[[false]]', '{"const":[[0]]}'],
  ['{"a":[{"b":true}]}', '{"const":{"a":[{"b":1}]}}'],
  ['{"a":[{"b":1}]}', '{"const":{"a":[{"b":1}]}}'],
  // number looseness deep
  ['{"a":[1e0,2.5]}', '{"const":{"a":[1,2.50]}}'],
  ['[0.0]', '{"enum":[[0],[false]]}'],
  // cross-type non-equality
  ['"1"', '{"enum":[1]}'],
  ['1', '{"enum":["1"]}'],
  ['null', '{"enum":[0,false]}'],
  ['[]', '{"enum":[{}]}'],
  ['{}', '{"const":[]}'],
  ['0', '{"const":""}'],
  // enum objects: key order, extra keys
  ['{"b":2,"a":1}', '{"const":{"a":1,"b":2}}'],
  ['{"a":1,"b":2,"c":3}', '{"enum":[{"a":1,"b":2}]}'],
  ['{"a":1}', '{"enum":[{"a":1,"b":2}]}'],
  // bool instance with number-like enum mixes
  ['true', '{"enum":[0,1,2]}'],
  ['false', '{"enum":[true,1]}'],
  ['true', '{"enum":[false,true]}'],
  // type edge: every JSON type against every simple type
  ['"s"', '{"type":["array","boolean","integer","number","null","object"]}'],
  ['5', '{"type":["array","boolean","integer","number","null","object"]}'],
  ['null', '{"type":["array","boolean","integer","number","string","object"]}'],
  // const/enum with strings containing escapes / unicode
  ['"héllo\\n"', '{"const":"héllo\\n"}'],
  ['"héllo"', '{"enum":["hello","héllo"]}'],
  // duplicate enum values
  ['1', '{"enum":[1,1,1.0]}'],
  ['true', '{"enum":[true,true]}'],
  // float boundaries
  ['1e308', '{"const":1e308}'],
  ['0.1', '{"const":0.1}'],
  ['123456789012345680', '{"const":123456789012345680}'],
  // large nested
  ['{"a":{"b":{"c":{"d":[1,{"e":false}]}}}}', '{"enum":[{"a":{"b":{"c":{"d":[1,{"e":0}]}}}}]}'],
  ['{"a":{"b":{"c":{"d":[1,{"e":false}]}}}}', '{"enum":[{"a":{"b":{"c":{"d":[1,{"e":false}]}}}}]}'],
];

