// Python jsonschema chooses the check by whether the divisor literal was a
// float: integer divisors use `instance % dB != 0`, float divisors use
// `int(instance / dB) != instance / dB`. JS cannot see whether the JSON
// literal had a decimal point, so we use Number.isInteger(divisor), which
// matches on all observable cases except integer-valued float literals
// (e.g. `3.0`), which are indistinguishable from `3` in JS.
//
// Overflow: when `instance / dB` overflows to +/-Infinity, Python's
// int(quotient) raises OverflowError; the bundled jsonschema (4.23.0) then
// falls back to the modulo check (empirically verified against the
// reference: 1e308 % 0.5 == 0 -> valid, 1e308 % 0.1 != 0 -> invalid).
export function* multipleOf(validator, divisor, instance, schema) {
  if (!validator.isType(instance, 'number')) return;

  let failed;
  if (Number.isInteger(divisor)) {
    failed = instance % divisor !== 0;
  } else {
    const quotient = instance / divisor;
    if (Number.isFinite(quotient)) {
      failed = !Number.isInteger(quotient);
    } else {
      failed = instance % divisor !== 0;
    }
  }

