import json, random, subprocess, sys
random.seed(20260808)

def rand_val(d=0):
    r = random.random()
    if d > 2 or r < 0.45:
        return random.choice([0, 1, 1.0, 2, -1, 0.5, True, False, None, "a", "b", "", "1"])
    if r < 0.75:
        return [rand_val(d+1) for _ in range(random.randint(0, 3))]
    return {random.choice(["a","b","c"]): rand_val(d+1) for _ in range(random.randint(0, 3))}

def rand_inst():
    return [rand_val() for _ in range(random.randint(0, 6))]

def rand_subschema(d=0):
    r = random.random()
    if r < 0.15: return random.choice([True, False])
    if r < 0.45: return {"type": random.choice(["integer","number","string","boolean","null","array","object"])}
    if r < 0.6: return {"minimum": random.choice([-1,0,1,1.5]), "maximum": random.choice([1,2,10])}
    if r < 0.7 and d < 2: return {"items": rand_subschema(d+1)}
    if r < 0.8: return {"const": rand_val()}
    if r < 0.9: return {"enum": [rand_val(), rand_val(), rand_val()]}
    return {"minLength": random.randint(0,2), "maxLength": random.randint(0,3)}

def rand_schema():
    s = {}
    r = random.random()
    if r < 0.35:
        s["items"] = rand_subschema()
    elif r < 0.7:
        s["items"] = [rand_subschema() for _ in range(random.randint(0, 3))]
    if "items" in s and isinstance(s["items"], list) and random.random() < 0.7:
        s["additionalItems"] = random.choice([True, False, rand_subschema()])
    if random.random() < 0.4: s["contains"] = rand_subschema()
    if random.random() < 0.3: s["maxItems"] = random.randint(0, 4)
    if random.random() < 0.3: s["minItems"] = random.randint(0, 3)
    if random.random() < 0.5: s["uniqueItems"] = random.choice([True, False])
    if not s: s["uniqueItems"] = True
    return s

mismatches = 0
N = 400
for i in range(N):
    a = json.dumps(rand_inst())
    b = json.dumps(rand_schema())
    ref = subprocess.run(["/workspace/dataset/test18_executable", "--a", a, "--b", b],
