        mismatches += 1
        print("MISMATCH:", a, "|", b)
        print("ref :", ref.replace("\n", " "))
        print("mine:", mine.replace("\n", " "))
        if mismatches >= 10: break
print(f"done: {N} cases, {mismatches} mismatches")
